    function covers($x, $y) {
        global $position;
        foreach ($position as $index=>$pos) {
            $distX=abs($pos[0]-$x);
            $distY=abs($pos[1]-$y);
            if ($distY == 0 || $distX == 0 || $distX == $distY) {
                return false;
            }
        }
        return true;
    }

    $size=8;
    $solutions=0;

    // calculate all solutions
    for ($x=0; $x<$size; $x++) {
        for ($y=0; $y<$size; $y++) {
            if (covers($x,$y)) {
                $position[$x]=array($x,$y);
                if (count($position) === $size) {
                    $solutions++;
                    // do something with the solution
                    unset($position[$x]);
                } else {
                    eight_queens_solution($position);
                }
            }
        }
