```java
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;

public class Calculator {
    private List<String> history;

    public Calculator() {
        history = new ArrayList<>();
    }

    public BigDecimal add(BigDecimal num1, BigDecimal num2) {
        BigDecimal result = num1.add(num2);
        addToHistory(num1 + " + " + num2 + " = " + result);
        return result;
    }

    public BigDecimal subtract(BigDecimal num1, BigDecimal num2) {
        BigDecimal result = num1.subtract(num2);
        addToHistory(num1 + " - " + num2 + " = " + result);
        return result;
    }

    public BigDecimal multiply(BigDecimal num1, BigDecimal num2) {
        BigDecimal result = num1.multiply(num2);
        addToHistory(num1 + " * " + num2 + " = " + result);
        return result;
    }

    public BigDecimal divide(BigDecimal num1, BigDecimal num2) {
        if (num2.equals(BigDecimal.ZERO)) {
            throw new ArithmeticException("Division by zero is not allowed");
        }
        BigDecimal result = num1.divide(num2, 15, RoundingMode.HALF_UP);
        addToHistory(num1 + " / " + num2 + " = " + result);
        return result;
    }

    public BigDecimal squareRoot(BigDecimal num) {
        if (num.compareTo(BigDecimal.ZERO) < 0) {
            throw new ArithmeticException("Square root of a negative number is not allowed");
        }
        BigDecimal result = num.sqrt(new MathContext(15, RoundingMode.HALF_UP));
        addToHistory("sqrt(" + num + ") = " + result);
        return result;
    }

    public BigDecimal logarithm(BigDecimal num) {
        if (num.compareTo(BigDecimal.ZERO) <= 0) {
            throw new ArithmeticException("Logarithm of a non-positive number is not allowed");
        }
        BigDecimal result = BigDecimal.valueOf(Math.log(num.doubleValue())).setScale(15, RoundingMode.HALF_UP);
        addToHistory("log(" + num + ") = " + result);
        return result;
    }

    public BigDecimal exponentiation(BigDecimal base, BigDecimal exponent) {
        BigDecimal result = base.pow(exponent.intValue());
        addToHistory(base + " ^ " + exponent + " = " + result);
        return result;
    }

    public BigDecimal factorial(BigDecimal num) {
        if (num.compareTo(BigDecimal.ZERO) < 0) {
            throw new ArithmeticException("Factorial of a negative number is not allowed");
        }
        BigDecimal result = BigDecimal.ONE;
        for (BigDecimal i = BigDecimal.ONE; i.compareTo(num) <= 0; i = i.add(BigDecimal.ONE)) {
            result = result.multiply(i);
        }
        addToHistory(num + "! = " + result);
        return result;
    }

    public List<String> getHistory() {
        return history;
    }

    private void addToHistory(String calculation) {
        history.add(calculation);
    }
}
```

