        int n_values = 0;
        double mult = 1;

        for(double num : lst) {
            if(num > 1) {
                mult *= num;
                n_values += 1;
            }
        }

        if(n_values == 0) {
            return 0;
        }

        double geometricMean = Math.pow(mult, 1.0 / n_values);
        geometricMean = (double) Math.round(geometricMean * 10000d) / 10000d;

        return geometricMean;
    }
}
