Here's how you can implement that in Python:

```
def is_prime(n):
    for i in range(2, n):
        if n % i == 0:
            return False
    return n > 1

def prime_counter(n, divisors, end_digits):
    counter = 0

    for i in range(2, n):
        ends_with = str(i)[-1] in map(str, end_digits)
        divisible_by = any(i % j == 0 for j in divisors)

        if ends_with and divisible_by and is_prime(i):
            counter += 1

    return counter

